var WOOD='#ead9b8',WOODD='#cdb388',FELT='#a9d5b5',MAT='#dcd8cf',SCR='#4a4842',GLASS='#dde9f2',RED='#e07a6a',BLUE='#8fb6e0',GREEN='#7fbf8e',YEL='#f2cf6b';
function bx(x,y,w,h,f,o){return iR(x,y,w,h,Object.assign({fill:f||WHITE},o||{}))}
